import { Chip } from '@/registry/ndeko/ui/chip';

import { HERO } from './data';
import { IssuePreview } from './issue-preview';
import { WaitlistForm } from './waitlist-form';

export default function Heroes03() {
  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto grid max-w-6xl items-center gap-12 lg:grid-cols-[minmax(0,1fr)_24rem] lg:gap-16'>
        <div className='flex max-w-xl flex-col items-start gap-6'>
          <Chip color='var(--muted-foreground)' className='h-6 px-2'>
            {HERO.eyebrow}
          </Chip>
          <h1 className='text-4xl font-semibold text-balance sm:text-5xl'>
            {HERO.title}
          </h1>
          <p className='text-muted-foreground text-base text-pretty'>
            {HERO.description}
          </p>
          <WaitlistForm />
        </div>
        <div className='hidden lg:block'>
          <IssuePreview />
        </div>
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Field, FieldError, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { HERO } from './data';

type Status = 'idle' | 'submitting' | 'confirmed';

const SUBMIT_DELAY_MS = 900;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const PANEL_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const LABEL_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT: Transition = { duration: 0 };

const PANEL_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
};

const SPINNER_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function emailErrorOf(value: string) {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return 'Enter your email address to join the beta';
  }
  const isEmailShaped = EMAIL_PATTERN.test(trimmed);
  if (!isEmailShaped) {
    return 'Check the address, it should look like name@example.com';
  }
  return null;
}

function submitLabelOf(isSubmitting: boolean) {
  if (isSubmitting) {
    return 'Joining';
  }
  return 'Join the beta';
}

function panelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PANEL_VARIANTS;
}

function spinnerVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SPINNER_VARIANTS;
}

function labelTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LABEL_TRANSITION;
}

export function WaitlistForm() {
  const [email, setEmail] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasTriedSubmit, setHasTriedSubmit] = useState(false);
  const [status, setStatus] = useState<Status>('idle');
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const panelVariants = panelVariantsOf(shouldReduceMotion);
  const spinnerVariants = spinnerVariantsOf(shouldReduceMotion);
  const labelTransition = labelTransitionOf(shouldReduceMotion);
  const isSubmitting = status === 'submitting';
  const isConfirmed = status === 'confirmed';
  const hasError = error !== null;
  const submitLabel = submitLabelOf(isSubmitting);
  const trimmedEmail = email.trim();

  useEffect(() => {
    if (!isSubmitting) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setStatus('confirmed');
    }, SUBMIT_DELAY_MS);
    return () => window.clearTimeout(timeout);
  }, [isSubmitting]);

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    const nextEmail = event.target.value;
    setEmail(nextEmail);
    if (hasTriedSubmit) {
      setError(emailErrorOf(nextEmail));
    }
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const nextError = emailErrorOf(email);
    setHasTriedSubmit(true);
    setError(nextError);
    if (nextError) {
      inputRef.current?.focus();
      return;
    }
    setStatus('submitting');
  }

  function startOver() {
    setEmail('');
    setError(null);
    setHasTriedSubmit(false);
    setStatus('idle');
  }

  return (
    <AnimatedSize className='w-full max-w-md' contentClassName='relative'>
      <AnimatePresence mode='popLayout' initial={false}>
        {isConfirmed && (
          <motion.div
            key='confirmation'
            role='status'
            variants={panelVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={PANEL_TRANSITION}
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex items-start gap-3 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
          >
            <StatusOrb tone='success' />
            <div className='flex min-w-0 flex-col items-start gap-1'>
              <p className='text-sm font-medium'>Check your inbox</p>
              <p className='text-muted-foreground text-[13px]'>
                We sent a confirmation link to{' '}
                <span className='text-foreground font-medium break-all'>
                  {trimmedEmail}
                </span>
                . Open it to keep your place in the beta.
              </p>
              <Button
                variant='link'
                size='sm'
                className='h-auto px-0 py-0.5'
                onClick={startOver}
              >
                Use another address
              </Button>
            </div>
          </motion.div>
        )}
        {!isConfirmed && (
          <motion.form
            key='form'
            noValidate
            onSubmit={submit}
            variants={panelVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={PANEL_TRANSITION}
            className='flex flex-col gap-2'
          >
            <Field invalid={hasError}>
              <FieldLabel className='sr-only'>Email address</FieldLabel>
              <div className='flex flex-col gap-2 sm:flex-row'>
                <Input
                  ref={inputRef}
                  type='email'
                  name='email'
                  size='lg'
                  autoComplete='email'
                  placeholder='you@example.com'
                  value={email}
                  onChange={changeEmail}
                  readOnly={isSubmitting}
                />
                <Button
                  type='submit'
                  size='lg'
                  disabled={isSubmitting}
                  focusableWhenDisabled
                  className='data-disabled:opacity-100'
                >
                  <AnimatePresence mode='popLayout' initial={false}>
                    {isSubmitting && (
                      <motion.span
                        key='spinner'
                        className='flex'
                        variants={spinnerVariants}
                        initial='enter'
                        animate='visible'
                        exit='exit'
                        transition={PANEL_TRANSITION}
                      >
                        <LoaderCircleIcon className='animate-spin' />
                      </motion.span>
                    )}
                  </AnimatePresence>
                  <motion.span layout transition={labelTransition}>
                    {submitLabel}
                  </motion.span>
                </Button>
              </div>
              {hasError && <FieldError match>{error}</FieldError>}
            </Field>
            <p className='text-muted-foreground text-xs'>{HERO.note}</p>
          </motion.form>
        )}
      </AnimatePresence>
    </AnimatedSize>
  );
}

import { ClockIcon } from '@/registry/ndeko/lib/icons';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';

import { ISSUE } from './data';

function initialsOf(name: string) {
  const words = name.split(' ');
  const letters = words.map((word) => word.charAt(0));
  return letters.join('');
}

export function IssuePreview() {
  return (
    <div
      aria-hidden='true'
      className='bg-foreground/[0.025] rounded-2xl p-6 sm:p-8'
    >
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] motion-safe:animate-float flex flex-col gap-4 rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.14)]'>
        <div className='flex items-center gap-2.5'>
          <Avatar className='size-7'>
            <AvatarImage src={ISSUE.author.image} alt={ISSUE.author.name} />
            <AvatarFallback>{initialsOf(ISSUE.author.name)}</AvatarFallback>
          </Avatar>
          <div className='flex min-w-0 flex-col'>
            <p className='truncate text-[13px] font-medium'>
              {ISSUE.publication}
            </p>
            <p className='text-muted-foreground text-xs'>{ISSUE.number}</p>
          </div>
        </div>
        <div className='flex flex-col gap-1.5'>
          <p className='text-sm font-medium text-balance'>{ISSUE.subject}</p>
          <p className='text-muted-foreground text-[13px] leading-relaxed'>
            {ISSUE.excerpt}
          </p>
        </div>
        <div className='flex items-center gap-2'>
          <Chip color='var(--info)'>{ISSUE.status}</Chip>
          <span className='text-muted-foreground inline-flex items-center gap-1 text-xs tabular-nums'>
            <ClockIcon className='size-3.5' />
            {ISSUE.sendsAt}
          </span>
        </div>
      </div>
    </div>
  );
}

export const HERO = {
  eyebrow: 'Private beta',
  title: 'You write the issue, Fernpost sends it to every reader',
  description:
    'Drafts, schedules and subscriber lists in one quiet editor. Leave your address and we send an invite as soon as a seat opens.',
  note: 'One email when your invite is ready, nothing else until you sign in',
};

export const ISSUE = {
  author: { name: 'Ama Mensah', image: '/avatars/avatar-07.svg' },
  publication: 'Notes from the reading room',
  number: 'Issue 48',
  subject: 'Three books about rivers, and one about leaving',
  excerpt:
    'This week I read slowly on purpose. Here is what stayed with me, and the passage I copied into the margin of my notebook.',
  status: 'Scheduled',
  sendsAt: 'Tue 07:00',
};
